def _card(data, cid):
    return next(d for d in data['deals'] if d['id'] == cid)


def _set_sum(c, old_sum, old_eco, new, quote, url, n):
    import fact_edit_guard
    if c.get('sum') == new and c['eco'].get('sum') == new:
        return n
    assert c.get('sum') == old_sum and c['eco'].get('sum') == old_eco, (c['id'], c.get('sum'), c['eco'].get('sum'))
    c['sum'] = c['eco']['sum'] = new
    fact_edit_guard.log(c, 'sum', new, quote, url, ONEOFF_BY, ONEOFF_DAY)
    fact_edit_guard.log(c, 'eco.sum', new, quote, url, ONEOFF_BY, ONEOFF_DAY)
    return n + 1


def _first_src(c, label, url, n):
    src = c.setdefault('src', [])
    if src and src[0][1] == url:
        return n
    assert all(s[1] != url for s in src), (c['id'], url)
    src.insert(0, [label, url])
    return n + 1


def _oneoff_apply(data):
    import fact_edit_guard
    n = 0
    # --- первоисточники первыми в src (тексты на диск не ложатся: Qrator у РБК, капча у Forbes)
    n = _first_src(_card(data, 'g5850b57f'), 'РБК', RBC_YV, n)
    n = _first_src(_card(data, 'g8302ab18'), 'Forbes', FORBES_SPLAT, n)
    # --- оценки цены с именами — в сумму (docs/card_money.md, 18 ноября 2026)
    n = _set_sum(_card(data, 'g8e027018'), 'Не раскрыта', 'Не раскрыта', BIN_SUM, BIN_SUM_Q, VED_BIN, n)
    n = _set_sum(_card(data, 'gcd8d2664'), None, 'Не раскрыта (по оценке)', SKAZ_SUM, SKAZ_SUM_Q, RET_SKAZ, n)
    n = _set_sum(_card(data, 'g83ad1f72'), None, '—', CHEM_SUM, CHEM_SUM_Q, RET_CHEM, n)
    n = _set_sum(_card(data, 'gcd8fe39c'), None, '—', ASP_SUM, ASP_SUM_Q, KOM_ASP, n)
    # --- ge9d4edaa: доля по реестру, реестр сверен
    c = _card(data, 'ge9d4edaa')
    if c['eco'].get('share') != RL_SHARE:
        assert c['eco'].get('share') == 'Доля в ООО «Русский лен»; ее размер стороны не называли, комплекс куплен целиком.', c['eco'].get('share')
        c['eco']['share'] = RL_SHARE
        fact_edit_guard.log(c, 'eco.share', RL_SHARE, RL_SHARE_Q, DN_RL, ONEOFF_BY, ONEOFF_DAY)
        n += 1
    # --- примечания: реестр сверен, где искали
    for cid, key, text in (('ge9d4edaa', 'registry_owners', RL_CHECKED), ('gcd8fe39c', 'registry_owners', ASP_CHECKED),
                           ('g83ad1f72', 'registry_owners', CHEM_CHECKED), ('g8302ab18', 'registry_owners', SPL_CHECKED)):
        notes = _card(data, cid).setdefault('accepted_notes', {})
        if (notes.get('checked') or {}).get(key) != text:
            notes.setdefault('checked', {})[key] = text
            n += 1
    notes = _card(data, 'gcd8fe39c').setdefault('accepted_notes', {})
    if notes.get('searched') != ASP_SEARCHED:
        notes['searched'] = ASP_SEARCHED
        n += 1
    for cid, text in (('g62577a1d', KAR_NO_SELLER), ('gcd8fe39c', ASP_SELLER_NOTE), ('g83ad1f72', CHEM_SELLER_NOTE)):
        notes = _card(data, cid).setdefault('accepted_notes', {})
        if (notes.get('no_profile') or {}).get('seller') != text:
            notes.setdefault('no_profile', {})['seller'] = text
            n += 1
    # --- профиль покупателя без имени владельца в скобках (docs/card_title.md, 17 октября 2026)
    p = data['companies'][CHEM_PROFILE]
    if p.get('name') != CHEM_NAME_NEW:
        assert p.get('name') == CHEM_NAME_OLD, p.get('name')
        p['name'] = CHEM_NAME_NEW
        n += 1
    return n


def _oneoff_main(write):
    import json
    import os
    import sys
    root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
    sys.path.insert(0, os.path.join(root, 'pipeline'))
    import fact_edit_guard
    import mass_edit_guard
    path = os.path.join(root, 'static', 'data', 'deals_promoted.json')
    raw = open(path, encoding='utf-8').read()
    old, data = json.loads(raw), json.loads(raw)
    n = _oneoff_apply(data)
    if not n:
        print('Уже применено.')
        return 0
    mass_edit_guard.check(old, data, os.environ.get('MASS_OK'))
    bad = fact_edit_guard.unbacked(old, data)
    assert not bad, bad
    if not write:
        print('Сухой прогон: %d правок. Запись — с ключом --write.' % n)
        return 0
    fresh_raw = open(path, encoding='utf-8').read()
    fresh = json.loads(fresh_raw)
    _oneoff_apply(fresh)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(json.dumps(fresh, ensure_ascii=False, indent=1) + ('\n' if fresh_raw.endswith('\n') else ''))
    print('ЗАПИСАНО: %d правок.' % n)
    return 0


if __name__ == '__main__':
    import sys
    sys.exit(_oneoff_main('--write' in sys.argv[1:]))
